{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C10", "C18", "C83"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C10", "C18"],
  "claims": [
    {
      "claim": "The query is pitavastatin free acid; the closest measured context is cerivastatin, which shares the 3,5-dihydroxyhept-6-enoic acid side chain and a fluorophenyl substituent and had absolute oral bioavailability 60% (90% CI 51-70%) in fasted healthy young men, with the lower bound well above the 20% threshold.",
      "card_ids": ["C10", "C18"]
    },
    {
      "claim": "L3 card C83 shows that after an oral pitavastatin microdose, the pitavastatin lactone metabolite was measurable in plasma (rifampin GMR ~0.9 for Cmax and AUC), confirming oral absorption and systemic exposure of the pitavastatin scaffold; this is supportive but does not quantify absolute F.",
      "card_ids": ["C83"]
    },
    {
      "claim": "Other L3 oral exposure records for statins (e.g., rosuvastatin Cmax/AUC) show measurable systemic exposure after oral dosing, but they are not absolute bioavailability measurements and are less transferable than the cerivastatin context.",
      "card_ids": ["C66", "C72", "C99"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C83", "C66", "C72", "C99"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for pitavastatin free acid is present in the supplied cards.",
    "C83 measures the lactone metabolite after an oral microdose, not the free-acid F or fraction absorbed.",
    "Cerivastatin transfer does not control for differences in the quinoline/cyclopropyl core versus the cerivastatin pyridine core, transporter effects, or first-pass metabolism.",
    "The physicochemical prior is uncertain because the molecule is fully ionized at pH 7.4; no direct permeability or first-pass data for the query are supplied."
  ],
  "decision_summary": "The query is pitavastatin free acid. The closest measured context, cerivastatin, has absolute oral bioavailability 60% (90% CI 51-70%), well above the 20% threshold. L3 adds oral exposure evidence for the pitavastatin scaffold (lactone metabolite measurable after oral microdose) and for other statins, supporting absorption without providing a direct F value. No contradictory evidence appears. Prediction remains high with moderate confidence."
}

